function addressAssist(input,host){if(!input||!host)return;input.placeholder='Dirección, coordenadas (8.98, -79.52) o enlace de Google Maps';const draw=()=>{host.innerHTML=mapBox(input.value)};let timer;input.addEventListener('input',()=>{clearTimeout(timer);timer=setTimeout(draw,700)});const geo=document.createElement('button');geo.type='button';geo.textContent='Usar mi ubicación actual';geo.className='geo-button';geo.onclick=()=>{if(!navigator.geolocation)return toast('Este navegador no permite obtener la ubicación.');geo.disabled=true;navigator.geolocation.getCurrentPosition(p=>{input.value=`${p.coords.latitude.toFixed(6)}, ${p.coords.longitude.toFixed(6)}`;input.dispatchEvent(new Event('input',{bubbles:true}));draw();geo.disabled=false},()=>{toast('No se pudo obtener la ubicación (permiso denegado o sin señal).');geo.disabled=false},{enableHighAccuracy:true,timeout:15000})};input.insertAdjacentElement('afterend',geo);draw()}
