async function fileSection(kind,r){const host=document.createElement('section');host.className='panel';host.innerHTML='<h2>Archivos adjuntos</h2><div id="attached-files"></div><label class="field file-label">Adjuntar archivo<input id="upload-file" type="file" accept=".pdf,.png,.jpg,.jpeg,.webp,.docx,.xlsx,.txt"></label><button id="upload-button" style="margin-top:12px">Subir archivo</button>';$('#related').append(host);const items=await api('/erp/files?record_id='+encodeURIComponent(r.id));if(r.file_id&&!items.some(f=>f.id===r.file_id)){const all=await api('/erp/files').catch(()=>[]);items.push(...all.filter(f=>f.id===r.file_id))}/* file_id: adjunto único de versiones anteriores */const size=n=>n>=1048576?(n/1048576).toFixed(1)+' MB':Math.max(1,Math.round(n/1024))+' KB';$('#attached-files').innerHTML=items.length?`<ul class="file-list">${items.map(f=>`<li><button data-download="${esc(f.id)}" data-filename="${esc(f.filename)}">${esc(f.filename)}</button> <span class="subtle">${size(f.size||0)} · ${date(f.created_at)}</span></li>`).join('')}</ul>`:'<p class="subtle">Sin archivos asociados.</p>';host.querySelectorAll('[data-download]').forEach(b=>b.onclick=guard(()=>download('/erp/files/'+b.dataset.download+'/download',b.dataset.filename)));$('#upload-button').onclick=guard(async()=>{const b=$('#upload-button'),f=$('#upload-file').files[0];if(!f)throw Error('Selecciona un archivo.');b.disabled=true;try{const fd=new FormData();fd.append('file',f);fd.append('record_kind',kind);fd.append('record_id',r.id);await api('/erp/files','POST',fd);toast('Archivo guardado');await detail(kind,await api('/erp/records/'+kind+'/'+r.id))}finally{b.disabled=false}})}
