function pricingHint(d){if(!d)return '';const b=d.basis||{};const gg=d.overhead_source==='auto_capped'?`Gastos generales: <strong>${esc(d.indirect_percent)} %</strong> (límite automático).`:d.overhead_source==='auto'?`Gastos generales calculados automáticamente: <strong>${esc(d.indirect_percent)} %</strong> = ${money(b.monthly_fixed_costs)} de gastos fijos al mes ÷ ${money(b.monthly_direct_cost)} de costo directo mensual promedio de tus obras (últimos ${esc(b.months)} meses).`:d.overhead_source==='setting'?`Gastos generales de Configuración: <strong>${esc(d.indirect_percent)} %</strong>${b.monthly_fixed_costs?' (aún no hay costos de obra registrados en los últimos meses para calcularlo)':' (registra tus gastos fijos mensuales para calcularlo con tus datos)'}.`:'Sin gastos generales configurados: agrega tus gastos fijos mensuales o un porcentaje en Configuración.';const r=d.margin_rule,ut=d.margin_source==='rule'?`Utilidad automática: <strong>${esc(r.high)} %</strong> en trabajos de ${money(r.threshold)} o más y <strong>${esc(r.low)} %</strong> en trabajos menores (se ajusta al calcular).`:d.margin_source==='setting'?`Utilidad de Configuración: <strong>${esc(d.margin_percent)} %</strong>.`:'Sin utilidad por defecto en Configuración.';return `<div class="pricing-hint">${gg} ${ut}${d.warning?`<br><span class="up">${esc(d.warning)}</span>`:''}</div>`}
