async function users(){const r=await api('/erp/users'),rows=Array.isArray(r)?r:r.items||r.users||[];$('#content').innerHTML=heading('Cuentas y permisos','Cada persona accede con su cuenta y su rol.',`<button class="primary" id="new-user">Crear cuenta</button>`)+`<div class="table-wrap"><table><thead><tr><th>Nombre</th><th>Usuario</th><th>Rol</th><th>Obras asignadas</th></tr></thead><tbody>${rows.map(u=>`<tr><td>${esc(u.name)}</td><td>${esc(u.username)}</td><td>${esc(u.role)}</td><td>${esc((u.projects||[]).map(recordName).join(', ')||'Según permisos del rol')}</td></tr>`).join('')}</tbody></table></div>`;$('#new-user').onclick=guard(async()=>{const works=await records('works');$('#content').innerHTML=heading('Nueva cuenta','Configura el acceso individual del integrante.')+`<form id="user-form" class="panel editor"><div id="form-error" class="notice error" hidden></div><div class="form-grid">${(await Promise.all(['name!','username!','password!'].map(s=>fieldMarkup(s,{})))).join('')}<label class="field">Rol<select name="role"><option value="worker">Trabajador</option><option value="foreman">Encargado de obra</option><option value="estimator">Estimador</option><option value="coordinator">Coordinador</option><option value="admin">Administrador</option></select></label><label class="field full">Obras asignadas<select name="projects" multiple>${works.map(w=>`<option value="${w.id}">${esc(w.name)}</option>`).join('')}</select><small>Usa Ctrl o Cmd para seleccionar varias obras.</small></label></div><div class="form-footer"><button type="button" id="cancel-user">Cancelar</button><button class="primary">Crear cuenta</button></div></form>`;$('#cancel-user').onclick=guard(users);$('#user-form').onsubmit=guard(async e=>{e.preventDefault();const f=new FormData(e.target),body=Object.fromEntries(f);body.projects=f.getAll('projects');await api('/erp/users','POST',body);toast('Cuenta creada');await users()})})}
async function settings(){const [info,rows,pricing,company,ai,mail,inst]=await Promise.all([api('/erp/integrations'),records('settings',true),api('/erp/quotes/defaults').catch(()=>null),api('/erp/company'),api('/erp/ai/config').catch(()=>null),api('/erp/mail/config').catch(()=>null),api('/erp/installer/config').catch(()=>null)]);const v=k=>esc((company.fields.find(f=>f.key===k)||{}).value||''),managed=new Set(company.managed_setting_ids),others=rows.filter(r=>!managed.has(r.id));const aiState=!ai?'Sin acceso':ai.enabled&&ai.configured?`<span class="status approved">Conectada</span> Modelo ${esc(ai.model)} · clave ${esc(ai.key_hint)}`:ai.key_configured?`<span class="status pending">Desactivada</span> Clave guardada ${esc(ai.key_hint)}${ai.model?' · modelo '+esc(ai.model):' · falta elegir modelo'}`:'<span class="status">Sin conectar</span>';$('#content').innerHTML=heading('Configuración','Datos de la empresa, costos, inteligencia artificial y respaldos.')+`<section class="panel"><h2>Datos de la empresa</h2><p class="subtle">Aparecen en el encabezado del PDF de cotización. Al emitir, se guarda una copia con el documento: los cambios posteriores no alteran cotizaciones emitidas.</p><form id="company-form" class="form-grid"><label class="field full">Nombre de la empresa<input name="name" value="${v('name')}" placeholder="JG Soluciones PA" autocomplete="organization"></label><div class="field-pair"><label class="field">RUC<input name="ruc" value="${v('ruc')}" placeholder="8-888-1234" inputmode="text"></label><label class="field">DV<input name="dv" value="${v('dv')}" placeholder="56" inputmode="numeric" maxlength="2"></label></div><label class="field">Teléfono<input name="phone" value="${v('phone')}" placeholder="+507 6000-0000" autocomplete="tel"></label><label class="field">Correo<input name="email" type="email" value="${v('email')}" placeholder="cotizaciones@empresa.com" autocomplete="email"></label><label class="field full">Dirección<input name="address" value="${v('address')}"></label><div id="company-map" class="full"></div><label class="field full">Condiciones adicionales (una por línea)<textarea name="conditions" placeholder="Ej.: Garantía de 6 meses en mano de obra">${v('conditions')}</textarea></label><div class="form-footer full"><span class="subtle" id="company-status"></span><button type="submit" class="primary">Guardar datos de la empresa</button></div></form></section><section class="panel"><h2>Costos y utilidad</h2>${pricing?`<div class="pricing-summary"><div><span>Gastos generales en cotizaciones nuevas</span><strong>${esc(pricing.indirect_percent)} %</strong><small>${pricing.overhead_source==='auto'?'Calculado con tus datos':pricing.overhead_source==='auto_capped'?'Calculado y limitado a 50 %':pricing.overhead_source==='setting'?'Valor de respaldo':'Sin base: 0 %'}</small></div><div><span>Utilidad en cotizaciones nuevas</span><strong>${pricing.margin_rule?esc(pricing.margin_rule.high)+' % / '+esc(pricing.margin_rule.low)+' %':esc(pricing.margin_percent)+' %'}</strong><small>${pricing.margin_rule?'≥ '+money(pricing.margin_rule.threshold)+' / menores':'Sin tramos'}</small></div><div><span>Costo directo mensual promedio</span><strong>${money(pricing.basis.monthly_direct_cost)}</strong><small>Obras, últimos ${esc(pricing.basis.months)} meses</small></div></div>${pricingHint(pricing)}`:''}<form id="pricing-form" class="form-grid"><label class="field">Gastos fijos mensuales (USD)<input name="monthly_fixed_costs" type="number" min="0" step="0.01" value="${v('monthly_fixed_costs')}"></label><label class="field">Utilidad trabajos de USD 200 o más (%)<input name="margin_high" type="number" min="0" max="100" step="0.01" value="${v('margin_high')}"></label><label class="field">Utilidad trabajos menores de USD 200 (%)<input name="margin_low" type="number" min="0" max="100" step="0.01" value="${v('margin_low')}"></label><label class="field">Gastos generales de respaldo (%) · vacío = 0 %<input name="overhead_percent" type="number" min="0" max="100" step="0.01" value="${v('overhead_percent')}"></label><div class="form-footer full"><span class="subtle">Los gastos generales se calculan solos: gastos fijos ÷ costo directo mensual de tus obras.</span><button type="submit" class="primary">Guardar costos y utilidad</button></div></form></section><section class="panel" id="ai-panel"><h2>Inteligencia artificial (OpenAI)</h2><p class="ai-state">${aiState}</p><p class="subtle">Se usa para calcular el APU de las partidas y sugerir partidas del catálogo. La clave se guarda solo en el servidor (archivo privado) y nunca se muestra completa. Cada consulta consume saldo de tu cuenta de OpenAI. Crea la clave en <a href="https://platform.openai.com/api-keys" target="_blank" rel="noopener noreferrer">platform.openai.com/api-keys</a>.</p><form id="ai-form" class="form-grid"><label class="field full">Clave API de OpenAI<input name="api_key" type="password" autocomplete="off" spellcheck="false" placeholder="${ai?.key_configured?'Guardada '+esc(ai.key_hint)+' · escribe otra para reemplazarla':'sk-…'}"></label><div class="field full"><button type="button" id="ai-test">Probar clave y cargar modelos</button> <span class="subtle" id="ai-test-result"></span></div><label class="field">Modelo<select name="model" id="ai-model">${ai?.model?`<option value="${esc(ai.model)}" selected>${esc(ai.model)}</option>`:'<option value="">Prueba la clave para ver los modelos…</option>'}</select></label><label class="field check"><input type="checkbox" name="enabled" ${ai?.enabled?'checked':''}> Activar la IA en el ERP</label><div class="form-footer full"><button type="button" class="danger" id="ai-remove" ${ai?.source==='panel'?'':'hidden'}>Quitar clave</button><button type="submit" class="primary">Guardar conexión</button></div></form></section>${mail?`<section class="panel" id="mail-panel"><h2>Correo y acceso</h2><p class="ai-state">${mail.configured?'<span class="status approved">Listo</span> Los códigos llegan a '+esc(mail.admin_email):'<span class="status">Sin configurar</span> Sin esto nadie puede entrar desde otro equipo'}</p><p class="subtle">Para entrar desde otro equipo, la persona escribe su correo y el servidor envía un código de 6 dígitos <strong>a tu correo</strong>; el código no se repite, vale 10 minutos y se usa una vez. Para enviar correos se usa una cuenta de Gmail con verificación en 2 pasos y una <a href="https://myaccount.google.com/apppasswords" target="_blank" rel="noopener noreferrer">contraseña de aplicación</a> (16 letras). Tu acceso por el icono de este equipo no cambia.</p><form id="mail-form" class="form-grid"><label class="field">Correo del administrador (recibe los códigos)<input name="admin_email" type="email" value="${esc(mail.admin_email)}" required></label><label class="field">Cuenta de Gmail que envía<input name="sender" type="email" value="${esc(mail.sender)}" placeholder="tucuenta@gmail.com" required></label><label class="field">Contraseña de aplicación de Google<input name="app_password" type="password" autocomplete="off" spellcheck="false" placeholder="${mail.password_configured?'Guardada · escribe otra para reemplazarla':'xxxx xxxx xxxx xxxx'}"></label><label class="field">Nombre del remitente<input name="sender_name" value="${esc(mail.sender_name)}"></label><div class="form-footer full"><button type="button" id="mail-test" ${mail.configured?'':'disabled'}>Enviar correo de prueba</button><button type="submit" class="primary">Guardar correo</button></div></form></section>`:''}${inst?`<section class="panel" id="installer-panel"><h2>Instalador para otros equipos</h2><p class="ai-state">${inst.configured?'<span class="status approved">Listo para descargar</span> Servidor '+esc(inst.server_address)+':'+esc(inst.port)+' · clave '+esc(inst.key_hint):'<span class="status">Sin configurar</span>'}</p><p class="subtle">El instalador instala Tailscale (red privada, sin dominio ni exposición a internet), une el equipo a tu red sin pedir cuentas y crea el icono “JG Costos IA”. Después la persona solo entra con su correo y el código que tú le das. <strong>El archivo contiene la clave de tu red privada: compártelo solo con personas autorizadas.</strong></p><details class="howto"><summary>Cómo obtener la clave de Tailscale (una vez)</summary><ol><li>En <a href="https://login.tailscale.com/admin/settings/keys" target="_blank" rel="noopener noreferrer">Tailscale → Settings → Keys</a>, pulsa <em>Generate auth key</em>.</li><li>Marca <em>Reusable</em> y <em>Pre-approved</em>, añade la etiqueta <code>tag:jg-erp</code> y elige vencimiento (máx. 90 días).</li><li>Recomendado: en <em>Access controls</em>, permite a <code>tag:jg-erp</code> llegar solo al servidor por el puerto ${esc(inst.port)}, así esos equipos no ven nada más de tu red.</li><li>Pega la clave aquí (empieza por <code>tskey-</code>). La dirección del servidor es su IP de Tailscale (100.x.x.x).</li></ol></details><form id="installer-form" class="form-grid"><label class="field full">Clave de Tailscale (auth key)<input name="auth_key" type="password" autocomplete="off" spellcheck="false" placeholder="${inst.key_configured?'Guardada '+esc(inst.key_hint)+' · escribe otra para reemplazarla':'tskey-auth-…'}"></label><label class="field">Dirección del servidor en Tailscale<input name="server_address" value="${esc(inst.server_address)}" placeholder="100.x.x.x"></label><label class="field">Puerto<input name="port" type="number" min="1" max="65535" value="${esc(inst.port)}"></label><div class="form-footer full"><span></span><button type="submit" class="primary">Guardar instalador</button></div></form>${inst.configured?`<div class="installer-downloads"><button type="button" data-installer="linux">Descargar para Linux</button><button type="button" data-installer="windows">Descargar para Windows</button><button type="button" data-installer="macos">Descargar para Mac</button></div><p class="subtle">Linux: <code>bash instalar-jg-costos-ia-linux.sh</code> · Windows: doble clic al .cmd (acepta el permiso de administrador) · Mac: doble clic al .command (si lo bloquea, clic derecho → Abrir) y permite la VPN de Tailscale.</p>`:''}</section>`:''}<section class="panel"><h2>Integraciones</h2><dl class="record-meta"><div><dt>Base de datos principal</dt><dd>${esc(info.storage||'SQLite')}</dd></div><div><dt>Google Drive / Sheets</dt><dd>${info.google?.configured?'Credencial configurada':'Sin credencial configurada'}</dd></div><div><dt>Mapas</dt><dd>Google Maps (sin clave)</dd></div></dl>${info.sheet_url&&/^https:\/\//.test(info.sheet_url)?`<a class="button" href="${esc(info.sheet_url)}" target="_blank" rel="noopener noreferrer">Abrir hoja de Google</a>`:''}</section><section class="panel"><div class="panel-heading"><h2>Otros parámetros</h2><button id="new-setting">Agregar parámetro</button></div>${others.length?others.map(r=>`<div class="panel-heading"><div><strong>${esc(r.name)}</strong><p class="subtle">${esc(r.value)}</p></div><button data-setting="${r.id}">Editar</button></div>`).join(''):'<p class="subtle">Sin otros parámetros.</p>'}</section><section class="panel"><h2>Respaldo y trazabilidad</h2><p class="subtle">Crea una copia consistente de la base de datos. Los archivos adjuntos deben conservarse junto con el respaldo.</p><div class="actions"><button id="backup" class="primary">Crear respaldo</button><button id="audit">Ver auditoría</button><button id="accounts">Cuentas y permisos</button></div><div id="backup-result"></div></section>`;addressAssist($('#company-form [name=address]'),$('#company-map'));const saveCompany=form=>guard(async e=>{e.preventDefault();const b=e.submitter;if(b)b.disabled=true;try{await api('/erp/company','PUT',Object.fromEntries(new FormData(form)));delete cache.settings;toast('Datos guardados');await settings()}finally{if(b)b.disabled=false}});$('#company-form').onsubmit=saveCompany($('#company-form'));$('#pricing-form').onsubmit=saveCompany($('#pricing-form'));$('#ai-test').onclick=guard(async()=>{const b=$('#ai-test');b.disabled=true;$('#ai-test-result').textContent='Probando…';try{const key=$('#ai-form [name=api_key]').value.trim(),r=await api('/erp/ai/test','POST',key?{api_key:key}:{}),current=$('#ai-model').value;$('#ai-model').innerHTML=r.models.map(m=>`<option value="${esc(m)}" ${m===current?'selected':''}>${esc(m)}</option>`).join('')||'<option value="">La cuenta no tiene modelos de texto</option>';$('#ai-test-result').innerHTML=`<span class="status approved">Clave válida</span> ${r.models.length} modelos disponibles`}catch(e){$('#ai-test-result').innerHTML=`<span class="up">${esc(e.message)}</span>`}finally{b.disabled=false}});$('#ai-form').onsubmit=guard(async e=>{e.preventDefault();const f=new FormData(e.target);await api('/erp/ai/config','PUT',{api_key:String(f.get('api_key')||'').trim()||null,model:f.get('model')||'',enabled:f.get('enabled')==='on'});toast('Conexión de IA guardada');await settings();document.getElementById('ai-panel')?.scrollIntoView()});$('#ai-remove').onclick=guard(async()=>{if(await confirmAction('Quitar clave de OpenAI','Se borrará la clave guardada en el servidor y la IA quedará desactivada.')){await api('/erp/ai/config','DELETE');toast('Clave eliminada');await settings()}});$('#new-setting').onclick=guard(()=>recordEditor('settings'));document.querySelectorAll('[data-setting]').forEach(b=>b.onclick=guard(()=>recordEditor('settings',rows.find(r=>r.id===b.dataset.setting))));$('#backup').onclick=guard(async()=>{const result=await api('/erp/backup','POST',{});$('#backup-result').innerHTML=`<p class="notice">${esc(result.message||'Respaldo creado: '+(result.filename||result.path||result.name||'copia registrada en el servidor'))}</p>`});$('#accounts').onclick=guard(users);$('#audit').onclick=guard(async()=>{const result=await api('/erp/audit'),rows=Array.isArray(result)?result:result.items||result.events||[];$('#content').innerHTML=heading('Auditoría','Acciones registradas por el sistema.')+`<div class="table-wrap"><table><thead><tr><th>Fecha</th><th>Actor</th><th>Acción</th><th>Registro</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${date(r.at||r.created_at)}</td><td>${esc(r.actor)}</td><td>${esc(r.action)}</td><td>${esc(r.subject||r.project||r.id)}</td></tr>`).join('')}</tbody></table></div>`});$('#mail-form')?.addEventListener('submit',guard(async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));if(!d.app_password)delete d.app_password;await api('/erp/mail/config','PUT',d);toast('Correo guardado');await settings();document.getElementById('mail-panel')?.scrollIntoView()}));$('#mail-test')?.addEventListener('click',guard(async()=>{const b=$('#mail-test');b.disabled=true;try{const r=await api('/erp/mail/test','POST',{});toast('Correo de prueba enviado a '+r.sent_to)}finally{b.disabled=false}}));$('#installer-form')?.addEventListener('submit',guard(async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));if(!d.auth_key)delete d.auth_key;await api('/erp/installer/config','PUT',d);toast('Instalador guardado');await settings();document.getElementById('installer-panel')?.scrollIntoView()}));document.querySelectorAll('[data-installer]').forEach(b=>b.onclick=guard(()=>download('/erp/installer/download/'+b.dataset.installer,{linux:'instalar-jg-costos-ia-linux.sh',windows:'instalar-jg-costos-ia-windows.cmd',macos:'instalar-jg-costos-ia-mac.command'}[b.dataset.installer])))}
const sessionStore={get(){try{const d=JSON.parse(localStorage.getItem('jg_session')||'null');return d&&d.expires_at*1000>Date.now()?d:null}catch{return null}},set(d){try{localStorage.setItem('jg_session',JSON.stringify({token:d.token,expires_at:d.expires_at}))}catch{}},clear(){try{localStorage.removeItem('jg_session')}catch{}}};
function login(email=''){token='';$('#session-label').textContent='Sesión no iniciada';$('#content').innerHTML=`<div class="login-wrap"><form id="login-form" class="panel login"><span class="brand-mark big" aria-hidden="true">J<span class="g">G</span></span><h1>Entrar a JG Costos IA</h1><p class="subtle">Escribe tu correo. Se enviará un código de acceso de 6 dígitos al administrador; pídeselo y escríbelo aquí.</p><div id="form-error" class="notice error" hidden></div><label class="field">Correo electrónico<input name="email" type="email" autocomplete="email" required value="${esc(email)}"></label><button class="primary" type="submit">Solicitar código</button></form></div>`;$('#login-form').onsubmit=guard(async e=>{e.preventDefault();const b=e.submitter;b.disabled=true;try{const mail=new FormData(e.target).get('email');const r=await api('/erp/auth/request','POST',{email:mail});codeStep(String(mail),r)}finally{b.disabled=false}})}
function codeStep(email,info){$('#content').innerHTML=`<div class="login-wrap"><form id="code-form" class="panel login"><span class="brand-mark big" aria-hidden="true">J<span class="g">G</span></span><h1>Escribe el código</h1><p class="subtle">${info.to_admin?'Se envió el código al administrador. Pídeselo por teléfono o WhatsApp.':'Te enviamos el código a tu correo.'} Vale 10 minutos y se usa una sola vez.</p><div id="form-error" class="notice error" hidden></div><label class="field">Código de 6 dígitos<input name="code" inputmode="numeric" autocomplete="one-time-code" pattern="[0-9 ]{6,7}" maxlength="7" required class="code-input"></label><button class="primary" type="submit">Entrar</button><button type="button" id="other-mail">Usar otro correo</button></form></div>`;$('[name=code]').focus();$('#other-mail').onclick=()=>login(email);$('#code-form').onsubmit=guard(async e=>{e.preventDefault();const b=e.submitter;b.disabled=true;try{const r=await api('/erp/auth/verify','POST',{email,code:new FormData(e.target).get('code')});token=r.token;sessionStore.set(r);await startSession()}finally{b.disabled=false}})}
async function startSession(){user=await api('/erp/auth/me');$('#session-label').innerHTML=esc(user.name||user.username||'Sesión local')+(sessionStore.get()?' · <a href="#" id="logout">Cerrar sesión</a>':'');$('#logout')?.addEventListener('click',async e=>{e.preventDefault();await api('/erp/auth/logout','POST',{}).catch(()=>{});sessionStore.clear();login()});api('/erp/company').then(c=>{const n=(c.fields||[]).find(x=>x.key==='name')?.value;if(n)document.querySelector('.brand small').textContent=n}).catch(()=>{});await navigate()}
$('#today').textContent=new Date().toLocaleDateString('es-PA',{day:'numeric',month:'long',year:'numeric'});$('#menu-toggle').onclick=()=>$('#sidebar').classList.toggle('open');$('#account-button').onclick=()=>{location.hash='team'};window.addEventListener('hashchange',()=>{if(token)navigate()});document.addEventListener('click',e=>{const a=e.target.closest('a[href^="#"]');if(!a||e.defaultPrevented||e.button!==0||e.ctrlKey||e.metaKey)return;const target=a.getAttribute('href').slice(1)||'dashboard';if(modules[target]&&('#'+target===location.hash||(!location.hash&&target==='dashboard'))){e.preventDefault();if(token)navigate()}});nav();(async()=>{try{const r=await fetch('/session');if(r.ok){const d=await r.json();token=d.token||''}}catch(e){}if(!token){const saved=sessionStore.get();if(saved){token=saved.token;try{await startSession();return}catch(e){sessionStore.clear();token=''}}}if(token){try{await startSession()}catch(e){login()}}else login()})();
